						type: "Literal",
						value: null,
						bigint: "1",
					},
					expected: true,
				},
				{
					nodeA: {
						type: "Literal",
						value: null,
						bigint: "1",
					},
					nodeB: {
						type: "Literal",
						value: null,
						bigint: "2",
					},
					expected: false,
				},
				{
					nodeA: {
						type: "Literal",
						value: 1n,
						bigint: "1",
					},
					nodeB: {
						type: "Literal",
						value: 1n,
						bigint: "1",
					},
					expected: true,
				},
				{
					nodeA: {
						type: "Literal",
						value: 1n,
						bigint: "1",
					},
					nodeB: {
						type: "Literal",
						value: 2n,
						bigint: "2",
					},
					expected: false,
				},
			];

			for (const { nodeA, nodeB, expected } of patterns) {
				it(`should return ${expected} if it compared ${util.format("%o", nodeA)} and ${util.format("%o", nodeB)}`, () => {
